    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [fmt([100, 180, 260, 50, 40, 695]), fmt([5]), fmt([4, 4, 4]), fmt([1, 2, 3, 4, 5]),
             fmt([5, 4, 3, 2, 1]), fmt([3, 5, 5, 7, 9, 9, 1, 2]), fmt([1, 10**9, 1, 10**9]),
             fmt([2, 1]), fmt([1, 2])]
    for n in (3, 5, 8, 12, 20, 40):
        for hi in (3, 10, 10**9):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    tests.append(fmt(list(range(1, N // 2 + 1)) + list(range(N // 2, 0, -1))))
    return tests

